/* CampusDesk independent offline browser fallback. Main maintained UI: frontend/src/main.jsx (React). */
(()=>{'use strict';
const R=document.getElementById('root'),names={dashboard:'Overview',assistant:'AI helpdesk',tickets:'My requests',new:'New request',knowledge:'Knowledge base',faculty:'Faculty directory',notifications:'Notifications'},icons={dashboard:'▦',assistant:'✳',tickets:'▤',new:'＋',knowledge:'▧',faculty:'◇',notifications:'♧'};
let state={tab:'dashboard',data:null,config:null,history:[],search:'',dept:'',selected:null,notice:'',error:'',busy:false,chatDrafts:{}};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(x,def='')=>String(x??def),pretty=x=>val(x,'—').replaceAll('_',' '),date=x=>x?new Date(x).toLocaleString():'—';
function norm(raw){let d={...raw};for(let k of ['tickets','notifications','articles','faculty'])d[k]=Array.isArray(d[k])?d[k].filter(x=>x&&typeof x==='object'):[];d.tickets=d.tickets.map(x=>({...x,subject:val(x.subject,'Untitled request'),department:val(x.department,'Administration'),status:val(x.status,'open')}));return d;}
async function api(path,body){const op=body===undefined?'GET':'POST';let r=await fetch(path,{method:op,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('Server did not return valid JSON ('+r.status+').')}if(!r.ok)throw Error(d.error||'HTTP '+r.status);return d;}
async function load(){state.config=await api('/api/config');state.data=norm(await api('/api/bootstrap'));}
function button(text,action='noop',cls='secondary',disabled=false){return `<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${esc(text)}</button>`}
function heading(k,t,desc){return `<div class="eyebrow">${esc(k)}</div><h1 class="heading">${esc(t)}</h1><p class="desc">${esc(desc)}</p>`;}
function render(){if(!state.data){R.innerHTML=`<div class="recovery"><h2>CampusDesk needs attention</h2><p>${esc(state.error||'Cannot reach the Java backend. Start CampusDesk and ensure the configured college Wi-Fi is connected.')}</p>${button('Try again','retry','primary')}</div>`;return;}
let nav=Object.entries(names).map(([key,title])=>`<button data-tab="${key}" class="${state.tab===key?'current':''}"><span>${icons[key]}</span>${title}</button>`).join('');
R.innerHTML=`<div class="shell"><aside class="nav"><div class="logo">C● CampusDesk<small>VNRVJIET · COLLEGE HELPDESK</small></div>${nav}<div class="foot">Jev routes · AGY answers · SEND_TO drafts<br>Local prototype, not a live campus portal</div></aside><div class="area"><div class="top"><span>CampusDesk / ${esc(names[state.tab])}</span><span class="tag">JAVA + CAMPUS WIFI</span></div><div class="mobile-nav">${nav}</div><main class="main">${state.error?`<div class="error">${esc(state.error)}</div>`:''}${state.notice?`<div class="success">${esc(state.notice)}</div>`:''}<div id="view">${screen()}</div></main></div></div>`;
let feed=R.querySelector('.chat-feed');if(feed)feed.scrollTop=feed.scrollHeight;
}
function screen(){let d=state.data;switch(state.tab){
case 'dashboard':{let active=d.tickets.filter(x=>!['closed','resolved'].includes(x.status)).length;return `<div class="hero"><div class="eyebrow">WELCOME TO CAMPUSDESK</div><h1>One place to ask.<br>A clear path to resolution.</h1><p>Ask AGY a question, let Jev choose the appropriate route, and review SEND_TO requests before submitting.</p>${button('Ask the AI helpdesk →','goto-assistant','primary')}</div><div class="stats"><div class="panel stat"><label>ACTIVE REQUESTS</label><strong>${active}</strong><span class="muted">Awaiting progress</span></div><div class="panel stat"><label>TOTAL REQUESTS</label><strong>${d.tickets.length}</strong><span class="muted">Saved in this workspace</span></div><div class="panel stat"><label>NOTIFICATIONS</label><strong>${d.notifications.filter(x=>!x.read).length}</strong><span class="muted">Unread updates</span></div></div><div class="panel"><h3>Quick access</h3><div class="action-row">${button('Ask AGY','goto-assistant')}${button('Create a ticket','goto-new')}${button('Find faculty','goto-faculty')}</div></div><div class="hint"><strong>Architecture:</strong> Student → Jev routing → authorized local records / AGY investigation → SEND_TO draft → student-approved ticket → status tracking.</div>`;}
case 'assistant':return `${heading('JEV ROUTING · AGY CHAT ENGINE','Ask CampusDesk','Describe the issue. Jev selects the workflow, and AGY responds when installed and authenticated.')}<div class="hint"><b>AGY</b> writes the chat response when available. <b>Jev</b> decides the route when configured. <b>SEND_TO</b> only drafts an escalation; it never silently contacts a staff member.</div><div class="chat"><div class="chat-feed" id="chat-feed">${state.history.length?state.history.map((m,i)=>`<div class="bubble ${m.role==='user'?'mine':''}"><b>${m.role==='user'?'You':'CampusDesk'}</b><div>${esc(m.text)}</div>${m.provider?`<small>Source: ${esc(m.provider)}</small>`:''}${m.route?`<small>Route: ${esc(m.route.path||'unknown')} · ${esc(m.route.provider||'local')} ${m.route.department?' · '+esc(m.route.department):''}</small>`:''}${m.draft?`<div class="action-row">${button('Review and submit SEND_TO draft','draft-'+i,'primary')}</div>`:''}</div>`).join(''):`<div class="empty"><h2>What can I help you solve?</h2><p>Try “My exam fee shows unpaid even though I paid.”</p><div class="action-row">${button('My fee shows unpaid','sample-fee')}${button('How do I submit a complaint?','sample-complaint')}</div></div>`}</div><form id="chat-form" class="chat-form"><textarea id="message" placeholder="Ask a college question…" rows="2" maxlength="1200" required></textarea><button class="primary" ${state.busy?'disabled':''}>${state.busy?'Thinking…':'Send →'}</button></form></div><p class="notice">Model credentials and account access are never exposed to the browser. Without AGY sign-in, answers are labeled as local guidance.</p>`;
case 'tickets':return `${heading('YOUR REQUESTS','My helpdesk requests','Submitted requests are stored locally; no official staff integration is claimed.')}<div class="panel">${button('Create request +','goto-new','primary')}<div class="stack" style="margin-top:15px">${d.tickets.length?d.tickets.map(t=>`<div class="row"><div class="detail"><strong>${esc(t.subject)}</strong><p>CD-${esc(t.id)} · ${esc(t.department)} · ${date(t.createdAt)}</p></div><span class="pill">${esc(pretty(t.status))}</span></div>`).join(''):'<div class="empty">No requests yet. Start with the AI helpdesk or create one manually.</div>'}</div></div>`;
case 'new':return `${heading('SEND_TO · USER CONFIRMATION','Create a request','Choose the department and review the details before saving.')}<div class="panel"><form id="ticket-form"><div class="field"><label for="subject">Subject</label><input id="subject" maxlength="140" required placeholder="Describe your problem briefly"></div><div class="field"><label for="department">Send to</label><select id="department">${['Administration','Examination Branch','Accounts','Subject Lecturer','Class Coordinator','Head of Department','Facilities','Student Affairs'].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="description">Details</label><textarea id="description" rows="6" maxlength="6000" required placeholder="What happened, and what support do you need?"></textarea></div><button class="primary" ${state.busy?'disabled':''}>Save request →</button></form></div><div class="notice">This records a local request. It will not be delivered to official college staff until an authorized integration is configured.</div>`;
case 'knowledge':return `${heading('VERIFIED LOCAL GUIDANCE','Knowledge base','Only records published by an authorized source are shown.')}<div class="panel stack">${d.articles.length?d.articles.map(a=>`<div class="row"><div class="detail"><strong>${esc(a.title)}</strong><p>${esc(a.content)}</p></div></div>`).join(''):'<div class="empty">No published guides yet.</div>'}</div>`;
case 'faculty':{let list=d.faculty.filter(x=>(!state.search||`${x.name||''} ${x.department||''}`.toLowerCase().includes(state.search.toLowerCase()))&&(!state.dept||x.department===state.dept));let departments=[...new Set(d.faculty.map(x=>x.department).filter(Boolean))].sort();return `${heading('PUBLIC COLLEGE DIRECTORY','Faculty members','Sourced from public VNRVJIET department listings; no live location or verified room information.')}<div class="panel"><div class="action-row"><input id="search" class="search" style="max-width:440px" value="${esc(state.search)}" placeholder="Search faculty or department"><select id="dept-filter" class="search" style="max-width:260px"><option value="">All departments</option>${departments.map(x=>`<option value="${esc(x)}" ${state.dept===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><p class="muted">${list.length} results / ${d.faculty.length} public listings</p><div class="directory">${list.slice(0,250).map(x=>`<div class="row"><div class="detail"><strong>${esc(x.name)}</strong><p>${esc(x.department)}</p>${x.source?`<p><a href="${esc(x.source)}" target="_blank" rel="noopener noreferrer">College source ↗</a></p>`:''}</div></div>`).join('')}</div></div>`;}
case 'notifications':return `${heading('ACTIVITY','Notifications','Ticket activity saved in your private local workspace.')}<div class="panel stack">${d.notifications.length?d.notifications.map(n=>`<div class="row"><div class="detail"><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p></div>${!n.read?button('Mark read','read-'+esc(n.id)):'<span class="pill">Read</span>'}</div>`).join(''):'<div class="empty">No notifications yet.</div>'}</div>`;
}}
async function safe(work){state.error='';state.notice='';state.busy=true;render();try{await work()}catch(e){state.error=e.message||'Something went wrong';}finally{state.busy=false;render()}}
function goto(tab){state.tab=tab;state.error='';state.notice='';render()}
R.addEventListener('click',async e=>{const t=e.target.closest('[data-tab],[data-action]');if(!t)return;if(t.dataset.tab){goto(t.dataset.tab);return;}let a=t.dataset.action;
if(a==='retry'){try{await load();state.error='';render()}catch(err){state.error=err.message;render()}return;}
if(a.startsWith('goto-')){goto(a.slice(5));return;}
if(a.startsWith('sample-')){const q=a==='sample-fee'?'My exam fee still shows unpaid even though I paid.':'How do I submit a complaint?';await ask(q);return;}
if(a.startsWith('draft-')){const m=state.history[Number(a.slice(6))];if(!m?.draft)return;state.tab='new';render();let draft=m.draft;R.querySelector('#subject').value=draft.subject||'';R.querySelector('#description').value=draft.description||'';R.querySelector('#department').value=draft.department||'Administration';return;}
if(a.startsWith('read-')){await safe(async()=>{await api('/api/notifications/read',{id:a.slice(5)});await load();state.notice='Marked as read.'})}
});
R.addEventListener('submit',async e=>{if(e.target.id==='chat-form'){e.preventDefault();let t=R.querySelector('#message');let q=t.value.trim();if(q)await ask(q);return;}if(e.target.id==='ticket-form'){e.preventDefault();const el=e.target;let data={subject:el.querySelector('#subject').value,department:el.querySelector('#department').value,description:el.querySelector('#description').value,priority:'medium'};await safe(async()=>{await api('/api/tickets',data);await load();state.tab='tickets';state.notice='Request saved locally.'})}});
R.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;let caret=e.target.selectionStart;render();let el=R.querySelector('#search');el?.focus();if(el)el.setSelectionRange(caret,caret);}});
R.addEventListener('change',e=>{if(e.target.id==='dept-filter'){state.dept=e.target.value;render();}});
async function ask(text){if(state.busy)return;state.history.push({role:'user',text});state.busy=true;state.tab='assistant';state.error='';render();try{let x=await api('/api/assistant',{message:text});state.history.push({role:'assistant',text:x.answer||'No answer received.',provider:x.agentProvider,route:x.route,draft:x.ticketDraft})}catch(e){state.history.push({role:'assistant',text:'Could not answer: '+e.message+'. No ticket was submitted.',provider:'Error'})}finally{state.busy=false;render()}}
window.addEventListener('error',e=>{state.error='A screen encountered an error. Refresh to retry.';console.error('CampusDesk UI error',e.error)});
load().then(render).catch(e=>{state.error=e.message;render()});
})();
